window.kbPageData["views/entry/k-2396deee96a157ea"] = {"key":"entry/k-2396deee96a157ea","state":{"route":"entry/k-2396deee96a157ea"},"node":{"id":"k-2396deee96a157ea","mode":"k","title":"印花税税目与税率","type":"制度与规则","domain":"经济","reading":"","intro":"","priority":100,"aliases":["印花税按税目适用不同税率"],"qs":["国考 2024 地市级 行测#13"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"纳税人应按《中华人民共和国印花税法》所附税目税率表确定适用税率，再以计税依据乘以适用税率计算应纳税额。","review":{"definition":"纳税人应按《中华人民共和国印花税法》所附税目税率表确定适用税率，再以计税依据乘以适用税率计算应纳税额。","explanation":"2022年7月1日起施行的《印花税法》在考试时适用，旧条例的按件定额规定随条例废止。附表的法定税率有五个不同数值，即万分之零点五、二点五、三、五和千分之一。自2023年8月28日起，证券交易印花税减半征收，按成交金额折算为万分之五。租赁等合同仍有适用千分之一的情形，因此单计证券交易减半对税率表的影响，仍可数出五个不同数值。B项所说的统一税率错误。","references":[{"source":"web-c168415f6ae6951c","location":"第四条、第八条、第二十条及所附《印花税税目税率表》","quote":"依照本法所附《印花税税目税率表》执行"},{"source":"web-26fd775d626ac093","location":"2023年第39号公告正文","quote":"自2023年8月28日起，证券交易印花税实施减半征收"}],"evidence":"所有印花税税目均按照统一的税率征收","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"questions":{"国考 2024 地市级 行测#13":{"paper":"国考 2024 地市级 行测","n":13,"mod":"常识判断","src":["92d0b72e86a6a33d568d.pdf",3],"asrc":["e1792c53900a45f1b9fa.pdf",5],"card":"19ed29428e92cdc85e5c364d","links":[{"id":"k-2396deee96a157ea","role":"直接考查","why":"判断统一税率的说法需要知道印花税税目存在税率差异。"}]}},"terms":{},"references":{"web-c168415f6ae6951c":{"name":"《中华人民共和国印花税法》","url":"https://wb.flk.npc.gov.cn/flfg/PDF/3b107a3136aa4454bcf6289c350d1d98.pdf"},"web-26fd775d626ac093":{"name":"财政部、税务总局《关于减半征收证券交易印花税的公告》","url":"https://shanxi.chinatax.gov.cn/web/detail/sx-11400-545-1780448"}},"topics":[],"units":{"k-2396deee96a157ea":[["国考 2024 地市级 行测#13"]]}};
